insert into public.concepts(id,course_id,slug,title,summary,order_index,content) values
('20000000-0000-4000-8000-000000000401','10000000-0000-4000-8000-000000000005','si-units','SI units','Base and derived units, prefixes and measurement standards.',0,$c${"explanation":"Measurement compares a physical quantity with a standard unit. The SI system has seven base units: metre (length), kilogram (mass), second (time), ampere (current), kelvin (temperature), mole (amount of substance) and candela (luminous intensity). Derived units are formed by multiplying or dividing base units, such as newton = kg m s⁻² and joule = kg m² s⁻². Prefixes scale units by powers of ten: kilo (10³), centi (10⁻²), milli (10⁻³), micro (10⁻⁶) and nano (10⁻⁹). Units must be consistent in an equation, and every measurement needs a unit.","examples":[{"problem":"Express 2.5 mm in metres.","solution":"1 mm = 10⁻³ m, so 2.5 mm = 2.5 × 10⁻³ m = 0.0025 m."},{"problem":"Write the SI unit of force in base units.","solution":"F = ma, so 1 N = 1 kg × 1 m/s² = 1 kg m s⁻²."}],"misconceptions":["The kilogram is not an SI base unit.","Prefixes multiply by powers of ten but do not change the unit family.","A numerical answer without a unit is a complete measurement."],"revision_notes":"Seven SI base units. Derived units come from equations. Prefixes: k, c, m, μ, n. Always state units."}$c$::jsonb),
('20000000-0000-4000-8000-000000000402','10000000-0000-4000-8000-000000000005','dimensions','Dimensions of physical quantities','Representing quantities with powers of mass, length and time.',1,$c${"explanation":"Dimensions express a physical quantity in terms of the base quantities mass M, length L, time T, electric current A, temperature K, amount of substance mol and luminous intensity cd. For example, velocity has dimensions [L T⁻¹], acceleration [L T⁻²], force [M L T⁻²] and energy [M L² T⁻²]. Dimensionless quantities, such as refractive index or relative density, have no dimensions. Quantities with the same dimensions can be added or equated, and dimensional formulae help check equations. Dimensions do not contain numerical factors.","examples":[{"problem":"Find the dimensions of pressure.","solution":"Pressure = force/area = [M L T⁻²]/[L²] = [M L⁻¹ T⁻²]."},{"problem":"Are angle and strain dimensional or dimensionless?","solution":"Both are dimensionless: angle is a ratio of lengths and strain is a ratio of lengths."}],"misconceptions":["Dimensions include the numerical coefficient of a formula.","All dimensionless quantities have the same units.","Different physical quantities can never share dimensions."],"revision_notes":"Use M, L, T and the other base symbols. Force [M L T⁻²], energy [M L² T⁻²], pressure [M L⁻¹ T⁻²]."}$c$::jsonb),
('20000000-0000-4000-8000-000000000403','10000000-0000-4000-8000-000000000005','significant-figures','Significant figures','Reporting measured values at a justified precision.',2,$c${"explanation":"Significant figures are the digits in a measurement that carry meaningful information about its precision. All non-zero digits are significant; zeros between non-zero digits are significant; leading zeros are not; trailing zeros after a decimal point are significant. In multiplication and division, the result keeps the smallest number of significant figures among the inputs. In addition and subtraction, the result keeps the smallest number of decimal places. Rounding should be done once, at the end, to avoid accumulating rounding error. A measurement should not claim more precision than its instrument provides.","examples":[{"problem":"How many significant figures are in 0.00450 m?","solution":"Three: 4, 5 and the trailing 0. The leading zeros are placeholders, not significant."},{"problem":"Multiply 2.4 m by 3.12 m. How should the area be reported?","solution":"The product is 7.488 m², but 2.4 has two significant figures, so report 7.5 m²."}],"misconceptions":["All zeros in a measured value are significant.","Addition uses the significant-figure rule for multiplication.","Extra digits from a calculator are always justified."],"revision_notes":"Multiplication/division: fewest significant figures. Addition/subtraction: fewest decimal places. Round only at the end."}$c$::jsonb),
('20000000-0000-4000-8000-000000000404','10000000-0000-4000-8000-000000000005','errors','Errors in measurement','Absolute, relative and percentage error; systematic and random effects.',3,$c${"explanation":"No measurement is exact. The absolute error is |measured value − true value|; the mean absolute error averages these magnitudes. Relative error is absolute error divided by the true value, and percentage error multiplies it by 100%. Systematic errors shift all readings in one direction, for example a zero error of an instrument. Random errors scatter above and below the true value and are reduced by repeating measurements and averaging. The least count of an instrument is the smallest value it can read, and it limits the precision of a single reading.","examples":[{"problem":"A length is measured as 4.9 cm but the true value is 5.0 cm. Find the percentage error.","solution":"Absolute error = 0.1 cm. Percentage error = (0.1/5.0) × 100% = 2%."},{"problem":"Repeating a measurement several times and averaging mainly reduces which type of error?","solution":"Random error; systematic error would remain unless the instrument is corrected."}],"misconceptions":["Averaging repeated readings removes a zero error.","Percentage error is the absolute error multiplied by 100.","Instrument least count does not limit precision."],"revision_notes":"Absolute error in the quantity’s unit. Percentage error = (Δa/a) × 100%. Average repeats to reduce random error."}$c$::jsonb),
('20000000-0000-4000-8000-000000000405','10000000-0000-4000-8000-000000000005','dimensional-analysis','Dimensional analysis','Using dimensions to check equations and derive relations.',4,$c${"explanation":"Dimensional analysis uses the principle of homogeneity: every term in a valid physical equation must have the same dimensions. It can check whether an equation is dimensionally consistent and can derive the form of a relation up to a dimensionless constant. For example, if the period of a pendulum depends on length and gravitational acceleration, dimensional reasoning gives T ∝ √(L/g). The method cannot determine numerical constants, and it cannot test equations involving sums of terms that are individually dimensionless, such as trigonometric relations.","examples":[{"problem":"Check dimensionally: v = u + at.","solution":"v and u are [L T⁻¹]; at is [L T⁻²][T] = [L T⁻¹]. All terms match, so the equation is dimensionally consistent."},{"problem":"Use dimensions to find how the time period of a simple pendulum depends on length L and g.","solution":"Let T ∝ Lᵃgᵇ. Then [T] = [L]ᵃ[L T⁻²]ᵇ gives b = -1/2 and a + b = 0, so a = 1/2 and T ∝ √(L/g)."}],"misconceptions":["A dimensionally correct equation is necessarily physically correct.","Dimensional analysis determines the exact numerical constant in a formula.","Terms with different dimensions can be added if their numbers match."],"revision_notes":"Principle of homogeneity: each term has the same dimensions. Gives form up to a constant. Cannot fix dimensionless factors."}$c$::jsonb),
('20000000-0000-4000-8000-000000000501','10000000-0000-4000-8000-000000000006','electric-charge','Electric charge','Quantisation, conservation and methods of charging.',0,$c${"explanation":"Electric charge is a fundamental property of matter. Charge is quantised: every charge is an integer multiple of the elementary charge e ≈ 1.6 × 10⁻¹⁹ C, so q = ne. Charge is conserved: it can be transferred but never created or destroyed. Charges of the same sign repel and opposite signs attract. Conductors allow charge to move freely, while insulators hold charge in place. A body can be charged by friction, by conduction through contact, or by induction without direct contact. In a neutral body the positive and negative charges are equal.","examples":[{"problem":"How many electrons make up a charge of -3.2 × 10⁻¹⁹ C?","solution":"n = q/e = (3.2 × 10⁻¹⁹)/(1.6 × 10⁻¹⁹) = 2 electrons."},{"problem":"A glass rod rubbed with silk becomes positive. What happens to the silk?","solution":"The silk gains electrons and becomes equally negatively charged; charge is conserved overall."}],"misconceptions":["Charge can be created by friction.","Charge is continuous rather than made of elementary units.","A charged insulator conducts charge as freely as a metal."],"revision_notes":"q = ne, e = 1.6 × 10⁻¹⁹ C. Charge is conserved. Friction transfers electrons; induction needs no contact."}$c$::jsonb),
('20000000-0000-4000-8000-000000000502','10000000-0000-4000-8000-000000000006','coulombs-law','Coulomb’s law','Force between point charges and superposition.',1,$c${"explanation":"Coulomb’s law gives the force between two point charges at rest: F = k|q₁q₂|/r², where k = 1/(4πε₀) ≈ 9 × 10⁹ N m² C⁻² and r is the separation. The force acts along the line joining the charges, is repulsive for like charges and attractive for opposite charges. It obeys Newton’s third law: each charge experiences an equal and opposite force. In a medium of relative permittivity εᵣ the force is reduced by a factor εᵣ. For more than two charges, the total force on one charge is the vector sum of the individual forces (superposition).","examples":[{"problem":"Find the force between 2 μC and 3 μC charges 0.30 m apart in air.","solution":"F = k|q₁q₂|/r² = (9 × 10⁹)(2 × 10⁻⁶)(3 × 10⁻⁶)/(0.30)² = 0.60 N, repulsive."},{"problem":"Two charges are moved twice as far apart. How does the force change?","solution":"The force becomes one-quarter as large, because F is inversely proportional to r²."}],"misconceptions":["Coulomb’s law force is proportional to 1/r rather than 1/r².","The force on the larger charge is greater.","The force acts perpendicular to the line joining the charges."],"revision_notes":"F = k|q₁q₂|/r², along the joining line. Like charges repel. Vector superposition for several charges."}$c$::jsonb),
('20000000-0000-4000-8000-000000000503','10000000-0000-4000-8000-000000000006','electric-field','Electric field','Force per unit positive test charge and point-charge fields.',2,$c${"explanation":"The electric field at a point is the electric force per unit positive test charge placed there: E = F/q₀. It is a vector, pointing in the direction of the force on a positive charge and opposite to the force on a negative charge. The field of a point charge q at distance r has magnitude E = k|q|/r² and points away from positive charge and toward negative charge. Fields from several charges add as vectors. Field strength is measured in newtons per coulomb (N C⁻¹), equivalently volts per metre.","examples":[{"problem":"Find the field 0.10 m from a 4.0 μC point charge.","solution":"E = kq/r² = (9 × 10⁹)(4.0 × 10⁻⁶)/(0.10)² = 3.6 × 10⁶ N C⁻¹, directed away from the positive charge."},{"problem":"A charge of -2.0 μC is placed in a field of 5.0 × 10⁴ N C⁻¹ to the right. Find the force.","solution":"F = qE = (2.0 × 10⁻⁶)(5.0 × 10⁴) = 0.10 N, directed opposite the field because the charge is negative."}],"misconceptions":["Electric field is a force rather than force per unit charge.","The field of a negative charge points toward it only for negative test charges.","Fields add as scalars."],"revision_notes":"E = F/q₀, unit N C⁻¹. Point charge E = k|q|/r². Field points away from +, toward −."}$c$::jsonb),
('20000000-0000-4000-8000-000000000504','10000000-0000-4000-8000-000000000006','field-lines','Electric field lines','Visualising field direction and strength.',3,$c${"explanation":"Electric field lines show the direction of the electric field: the tangent at any point gives the field direction, and the lines point away from positive charge and toward negative charge. The density of lines represents field strength, with closer lines meaning a stronger field. Field lines never cross, because the field has only one direction at a point. They begin on positive charges and end on negative charges, or extend to infinity. In a uniform field the lines are parallel and equally spaced.","examples":[{"problem":"Why do electric field lines never intersect?","solution":"An intersection would imply two field directions at the same point, which is impossible."},{"problem":"Sketch the field lines between two equal positive charges.","solution":"Lines leave both charges and bend away from each other; no lines connect the two positive charges directly, and there is a neutral point midway."}],"misconceptions":["Field lines point from negative to positive charge.","Field lines can cross at a point where fields cancel.","Denser field lines indicate a weaker field."],"revision_notes":"Lines leave + and enter −. Tangent gives direction; density gives strength. They never cross."}$c$::jsonb),
('20000000-0000-4000-8000-000000000505','10000000-0000-4000-8000-000000000006','electric-dipole','Electric dipole','Dipole moment, field and torque in a uniform field.',4,$c${"explanation":"An electric dipole consists of two equal and opposite charges separated by a distance. Its dipole moment is p = q × 2a, pointing from the negative to the positive charge, with unit coulomb metre (C m). On the axis of a short dipole the field is 2kp/r³ directed along p; on the perpendicular bisector it is kp/r³ directed opposite to p. In a uniform electric field the net force on a dipole is zero, but it experiences a torque τ = pE sin θ that tends to align p with the field. There is no net translational force in a uniform field.","examples":[{"problem":"Two charges ±2 μC are 0.10 m apart. Find the dipole moment.","solution":"p = q × 2a = (2 × 10⁻⁶)(0.10) = 2 × 10⁻⁷ C m, from the negative to the positive charge."},{"problem":"A dipole is placed parallel to a uniform field. What torque acts on it?","solution":"τ = pE sin 0° = 0; the dipole is in stable equilibrium when p is parallel to E."}],"misconceptions":["Net force on a dipole in a uniform field is nonzero.","Dipole moment points from positive to negative charge.","Torque is maximum when the dipole is parallel to the field."],"revision_notes":"p = q × 2a, from − to +. Axial field 2kp/r³, equatorial kp/r³. Torque τ = pE sin θ."}$c$::jsonb)
